# Reproduce Phase-1 mechanical line classes to lock classifier
from pathlib import Path
import re, hashlib
p = Path("/Users/frnkhrz/Documents/Peak_Trade/forensics/PEAK_TRADE_TEMPORARY_FORENSIC_WORKING_RUNBOOK.md")
data = p.read_bytes()
raw_lines = data.split(b"\n")
assert raw_lines[-1]==b""
raw_lines = raw_lines[:-1]

FENCE_RE = re.compile(rb"^( {0,3})([`~]{3,})(.*)$")
ATX_RE = re.compile(rb"^( {0,3})(#{1,6})(?:[ \t]+|$)(.*)$")
HR_RE = re.compile(rb"^( {0,3})(?:-{3,}|\*{3,}|_{3,})[ \t]*$")
UL_RE = re.compile(rb"^( {0,3})([-*+])[ \t]+")
OL_RE = re.compile(rb"^( {0,3})\d+[.)][ \t]+")
BQ_RE = re.compile(rb"^( {0,3})>")
TABLE_RE = re.compile(rb"^( {0,3})\|")
KV_RE = re.compile(rb"^[A-Z][A-Z0-9_]*=\S")
KV_RE2 = re.compile(rb"^[A-Z][A-Z0-9_]*=.*$")

def fence_match(line):
    m = FENCE_RE.match(line)
    if not m:
        return None
    return m.group(1), m.group(2), m.group(3)

depth=0
open_ch=None
open_len=0
classes={}
h1=0
cont=0
for line in raw_lines:
    fm = fence_match(line)
    typ=None
    if depth==0:
        opened=False
        if fm:
            indent, fence, rest = fm
            ch=fence[:1]; flen=len(fence)
            if not (ch==b"`" and b"`" in rest):
                depth=1; open_ch=ch; open_len=flen
                typ="FENCE_OPEN"; opened=True
        if not opened:
            if line == b"":
                typ="BLANK"
            elif ATX_RE.match(line):
                typ="HEADING"
                m=ATX_RE.match(line)
                if len(m.group(2))==1:
                    h1+=1
                    body=(m.group(3) or b"").decode()
                    if "Continuation" in body:
                        cont+=1
            elif HR_RE.match(line):
                typ="HORIZONTAL_RULE"
            elif TABLE_RE.match(line):
                typ="TABLE_ROW"
            elif UL_RE.match(line):
                typ="UNORDERED_LIST"
            elif OL_RE.match(line):
                typ="ORDERED_LIST"
            elif BQ_RE.match(line):
                typ="BLOCKQUOTE"
            elif KV_RE2.match(line) and b" " not in line.split(b"=",1)[0]:
                typ="KV_LINE"
            else:
                typ="NARRATIVE_OR_OTHER"
    else:
        closed=False
        if fm:
            indent, fence, rest = fm
            ch=fence[:1]; flen=len(fence)
            rest_ws = rest.strip(b" \t")==b""
            if ch==open_ch and flen>=open_len and rest_ws:
                typ="FENCE_CLOSE"; depth=0; closed=True
        if not closed:
            typ="FENCE_BODY"
    classes[typ]=classes.get(typ,0)+1

print("classes", dict(sorted(classes.items(), key=lambda x:-x[1])))
print("h1", h1, "cont", cont, "sum", sum(classes.values()))
